options.onMounted:
// sync การ์ดตอนเปิดฟอร์ม/เปิด record เก่า — onMounted ไม่มี arg value ต้องอ่านค่าเอง
const val = this.getValue();
const code = !!val ? val.code : null;

const labBox = this.getFieldRef('lab_box');
const xrayBox = this.getFieldRef('xray_box');

if (!!labBox) {
	code === 'lab' ? labBox.show() : labBox.hide();
}
if (!!xrayBox) {
	code === 'xray' ? xrayBox.show() : xrayBox.hide();
}

options.onChange:
// แสดง mapping card ตามชนิดบริการ — lab → lab_box, xray → xray_box, ที่เหลือ (order/nurs/med) ซ่อนทั้งคู่
// select-form-input คืนค่าเป็น object { value, label } — valueField ตั้งเป็น code ค่า .value จึงเป็น 'lab'/'xray'
const code = !!value ? value.code : null;

const labBox = this.getFieldRef('lab_box');
const xrayBox = this.getFieldRef('xray_box');

if (!!labBox) {
	code === 'lab' ? labBox.show() : labBox.hide();
}
if (!!xrayBox) {
	code === 'xray' ? xrayBox.show() : xrayBox.hide();
}

try {
  const formRef = this.getFormRef();
  const sectionCode = !!value && !!value.code ? value.code : '';
  const sectionId = !!value && !!value.value ? value.value : '';

  // :xq prefix = addParams แทรกค่าดิบ และตัดทิ้งทั้งท่อนเมื่อไม่มีค่า (SqlParser.ts:389,414)
  // → ไม่เลือก section = ไม่มีเงื่อนไข section ใน where เลย = แสดงทั้งหมด
  formRef.customParams.xqLabSection = !!sectionCode ? "AND `section.value` = '" + sectionCode + "'" : '';
  formRef.customParams.xqSubOrderSection = !!sectionId ? "AND `section.value` = CONVERT('" + sectionId + "', 'objectId')" : '';

  // ปิด dependEnable = ไม่มีใครล้าง cache ให้ → dropdown จะค้างรายการของ section เก่า
  // (handleRemote จะ return ทันทีถ้า itemsList ยังมีของ — SdSelectRemoteList.vue:621)
  const clearList = (fieldRef) => {
    if (!!fieldRef && !!fieldRef.fieldEditor && !!fieldRef.fieldEditor.selectInput) {
      fieldRef.fieldEditor.selectInput.handleClearList();
    }
  };

  clearList(formRef.getFieldRef('sub_order'));
  formRef.findFieldNameInSubForm('lab_item').forEach((refName) => clearList(formRef.getFieldRef(refName)));
} catch (error) {
  console.error('section filter sync failed', error);
}

try {
  if (!value || !value.specimen || !value.specimen.value) return;

  const specimenValue = value.specimen.value;
  const specimenLabel = value.specimen.label || '';

  const formRef = this.getFormRef();
  const subFormRef = formRef.subFormRefList['lab_specimen'];
  if (!subFormRef) return;

  // sub-form ที่ยังไม่เคยมีแถว formModel อาจเป็น null → addSubFormRow() จะ push ลง array ลอย แถวหายเงียบ
  const formData = formRef.getFormData(false);
  if (!Array.isArray(formData.lab_specimen)) formData.lab_specimen = [];

  const rows = formData.lab_specimen;
  const isDuplicate = rows.some((row) => !!row && !!row.speccode && row.speccode.value === specimenValue);
  if (isDuplicate) return;

  subFormRef.addSubFormRow();
  const lastRow = rows[rows.length - 1];
  if (!!lastRow) lastRow.speccode = { value: specimenValue, label: specimenLabel };
} catch (error) {
  console.error('auto-add lab_specimen failed', error);
}

// คำนวณอายุ(ปี) จากวันเกิด → ใส่ field age
const ageRef = this.refField('age');
if (!value) { if (ageRef) ageRef.setValue(null); return; }

const b = new Date(value);           // value = 'YYYY-MM-DD'
const now = new Date();
let age = now.getFullYear() - b.getFullYear();
const md = now.getMonth() - b.getMonth();
if (md < 0 || (md === 0 && now.getDate() < b.getDate())) age--;   // ยังไม่ถึงวันเกิดปีนี้ → ลบ 1

if (ageRef) ageRef.setValue(age >= 0 ? age : null);

